let publicContentDatabase: Database | null = null;

function readPublicContentDatabase() {
  if (!publicContentDatabase) {
    publicContentDatabase = createInitialDatabase();
  }
  return publicContentDatabase;
}

function hasCoreTables(value: unknown): value is Partial<Database> {
  const database = value as Partial<Database> | null;
  return (
    Array.isArray(database?.users) &&
    Array.isArray(database?.student_profiles) &&
    Array.isArray(database?.user_settings)
  );
}

type StateRow = {
  ai_tutor_message_records?: unknown;
  ai_tutor_usage_records?: unknown;
  payload: unknown;
  updated_at?: unknown;
  tenant_id?: unknown;
  state_kind?: unknown;
  revision?: unknown;
};

type PostgresExecutor = postgres.Sql | postgres.TransactionSql;

type SqliteStateMetadata = {
  revision: number;
  updatedAt: string;
};

let sqlite: DatabaseSync | null = null;
let postgresClient: postgres.Sql | null = null;
let aiTutorAuthAdmissionPostgresClient: postgres.Sql | null = null;
