let sqliteReadCache: Database | null = null;
let sqliteReadCacheUpdatedAt: string | null = null;
let sqliteReadCacheRevision: number | null = null;
let sqliteReadPromise: Promise<Database> | null = null;
const databaseIndexCache = new WeakMap<Database, DatabaseIndexes>();
const sqliteBusyTimeoutMs = 5_000;

function lessonPerfDebugEnabled() {
  const configured = process.env.LESSON_PERF_DEBUG?.trim().toLowerCase();
  return configured === "true" || configured === "1" || configured === "yes" || configured === "on";
}

function sqliteReadCacheDisabled() {
  const configured = process.env.HK_MATH_DISABLE_SQLITE_READ_CACHE?.trim().toLowerCase();
  return configured === "true" || configured === "1" || configured === "yes" || configured === "on";
}

function postgresHotAuthTablesEnabled() {
  if (storageProvider !== "postgres") return false;
  const configured = process.env.HK_MATH_POSTGRES_HOT_AUTH_TABLES?.trim().toLowerCase();
  return configured === "true" || configured === "1" || configured === "yes" || configured === "on";
}

function postgresHotAuthTablesShadowSyncEnabled() {
  return storageProvider === "postgres";
}

function postgresProjectionTablesShadowSyncEnabled() {
  return storageProvider === "postgres";
}

function logLessonPerf(label: string, startedAt: number) {
  if (!lessonPerfDebugEnabled()) return;
  console.info(`[lesson-perf] ${label}: ${Date.now() - startedAt}ms`);
}

function readCachedSqliteDatabase() {
  if (sqliteReadCacheDisabled()) return null;
  if (!sqliteReadCache) return null;
  const currentMetadata = currentSqliteStateMetadata();
  if (
    !currentMetadata ||
    currentMetadata.updatedAt !== sqliteReadCacheUpdatedAt ||
    currentMetadata.revision !== sqliteReadCacheRevision
  ) {
    clearSqliteReadCache();
    return null;
  }
  return sqliteReadCache;
}

function cacheSqliteDatabase(database: Database, metadata?: SqliteStateMetadata | null) {
  if (sqliteReadCacheDisabled()) {
    clearSqliteReadCache();
    return;
  }
  const currentMetadata = metadata ?? currentSqliteStateMetadata();
  if (!currentMetadata) {
    clearSqliteReadCache();
    return;
  }
  sqliteReadCache = database;
  sqliteReadCacheUpdatedAt = currentMetadata.updatedAt;
  sqliteReadCacheRevision = currentMetadata.revision;
}

function clearSqliteReadCache() {
  sqliteReadCache = null;
  sqliteReadCacheUpdatedAt = null;
  sqliteReadCacheRevision = null;
  sqliteReadPromise = null;
}

function sqliteStateMetadataFromRow(row?: StateRow): SqliteStateMetadata | null {
  if (
    typeof row?.updated_at !== "string" ||
    !Number.isSafeInteger(row.revision) ||
    (row.revision as number) < 1
  ) {
    return null;
  }
  return {
    revision: row.revision as number,
    updatedAt: row.updated_at
  };
}

function currentSqliteStateMetadata() {
  try {
    const row = getSqliteDatabase()
      .prepare("SELECT revision, updated_at FROM app_state WHERE id = ?")
      .get(stateRecordId) as StateRow | undefined;
    return sqliteStateMetadataFromRow(row);
  } catch {
    return null;
  }
}

function userTopicProgressKey(userId: string, topicId: string) {
  return `${userId}\u0000${topicId}`;
}

function userSlugProgressKey(userId: string, slug: string) {
  return `${userId}\u0000${slug}`;
}

function indexesForDatabase(database: Database) {
  const cached = databaseIndexCache.get(database);
  if (cached) return cached;

  const topicById = new Map(database.topics.map((topic) => [topic.id, topic]));
  const questionById = new Map(database.questions.map((question) => [question.id, question]));
  const lessonBySlug = new Map(database.lessons.map((lesson) => [lesson.slug, lesson]));
  const lessonByTopicId = new Map<string, LessonRecord>();
  const lessonsByCanonicalTopicId = new Map<string, LessonRecord[]>();
  const lessonBlocksBySlug = new Map<string, LessonBlockRecord[]>();
  const lessonProgressByUserTopicId = new Map<string, LessonProgressRecord>();
  const lessonProgressByUserSlug = new Map<string, LessonProgressRecord>();

  database.lessons.forEach((lesson) => {
    if (!lessonByTopicId.has(lesson.topic_id)) lessonByTopicId.set(lesson.topic_id, lesson);
    const topic = topicById.get(lesson.topic_id);
    const canonicalTopicId = lesson.canonical_topic_id ?? topic?.canonical_topic_id ?? lesson.topic_id;
    const canonicalLessons = lessonsByCanonicalTopicId.get(canonicalTopicId) ?? [];
    canonicalLessons.push(lesson);
    lessonsByCanonicalTopicId.set(canonicalTopicId, canonicalLessons);
  });

  database.lesson_blocks.forEach((block) => {
    const blocks = lessonBlocksBySlug.get(block.lesson_slug) ?? [];
    blocks.push(block);
    lessonBlocksBySlug.set(block.lesson_slug, blocks);
  });
  lessonBlocksBySlug.forEach((blocks) => blocks.sort((a, b) => a.sort_order - b.sort_order));

  database.lesson_progress.forEach((progress) => {
    lessonProgressByUserTopicId.set(userTopicProgressKey(progress.user_id, progress.topic_id), progress);
    if (progress.lesson_slug) {
      lessonProgressByUserSlug.set(userSlugProgressKey(progress.user_id, progress.lesson_slug), progress);
    }
  });

  const indexes = {
    topicById,
    questionById,
    lessonBySlug,
    lessonByTopicId,
    lessonsByCanonicalTopicId,
    lessonBlocksBySlug,
    lessonProgressByUserTopicId,
    lessonProgressByUserSlug
  };
  databaseIndexCache.set(database, indexes);
  return indexes;
}

function ensureSqliteAppStateMetadataColumns(storage: DatabaseSync) {
  const columns = new Set(
    (storage.prepare("PRAGMA table_info(app_state)").all() as Array<{ name?: unknown }>)
      .map((column) => (typeof column.name === "string" ? column.name : ""))
      .filter(Boolean)
  );

  if (!columns.has("tenant_id")) {
    storage.exec(`ALTER TABLE app_state ADD COLUMN tenant_id TEXT NOT NULL DEFAULT '${stateTenantId}'`);
  }
  if (!columns.has("state_kind")) {
    storage.exec(`ALTER TABLE app_state ADD COLUMN state_kind TEXT NOT NULL DEFAULT '${stateKind}'`);
  }
  if (!columns.has("revision")) {
    storage.exec("ALTER TABLE app_state ADD COLUMN revision INTEGER NOT NULL DEFAULT 0");
  }
}

function getSqliteDatabase() {
  if (sqlite) {
    if (!attestTeacherNoticeEmailOutboxSqliteSchema(sqlite)) {
      throw new Error("Teacher notice email outbox SQLite schema could not be attested.");
    }
    return sqlite;
  }

  sqlite = new DatabaseSync(dbPath);
  sqlite.exec(`
    PRAGMA busy_timeout = ${sqliteBusyTimeoutMs};
    PRAGMA journal_mode = WAL;
    PRAGMA foreign_keys = ON;

    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      applied_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS app_state (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL DEFAULT '${stateTenantId}',
      state_kind TEXT NOT NULL DEFAULT '${stateKind}',
      schema_version INTEGER NOT NULL,
      revision INTEGER NOT NULL DEFAULT 0,
      payload TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE INDEX IF NOT EXISTS app_state_updated_at_idx
      ON app_state(updated_at);
  `);
  ensureSqliteAppStateMetadataColumns(sqlite);
  sqlite.exec(`
    CREATE INDEX IF NOT EXISTS app_state_tenant_kind_updated_at_idx
      ON app_state(tenant_id, state_kind, updated_at);
  `);
  sqlite.exec("BEGIN IMMEDIATE");
  try {
    sqlite.exec(teacherNoticeEmailOutboxSqliteSchema);
    if (!attestTeacherNoticeEmailOutboxSqliteSchema(sqlite)) {
      throw new Error("Teacher notice email outbox SQLite schema could not be attested.");
    }
    sqlite.exec("COMMIT");
  } catch (error) {
    try {
      sqlite.exec("ROLLBACK");
    } catch {
      // Preserve the exact migration or attestation failure.
    }
    throw error;
  }

  const migration = sqlite.prepare("SELECT version FROM schema_migrations WHERE version = ?").get(schemaVersion);
  if (!migration) {
    sqlite
      .prepare("INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)")
      .run(schemaVersion, new Date().toISOString());
  }

  return sqlite;
}

function openDedicatedSqliteTransactionConnection() {
  const storage = new DatabaseSync(dbPath);
  storage.exec(`
    PRAGMA busy_timeout = ${sqliteBusyTimeoutMs};
    PRAGMA foreign_keys = ON;
  `);
  return storage;
}

async function withSqliteImmediateTransaction<T>(
  operation: (storage: DatabaseSync) => T | Promise<T>
) {
  await mkdir(dbDirectory, { recursive: true });
  // Schema setup happens before the dedicated transaction is opened. Every
  // read-modify-write below then uses one connection from BEGIN through COMMIT.
  getSqliteDatabase();
  const storage = openDedicatedSqliteTransactionConnection();
  let transactionOpen = false;
  let operationFailed = false;
  try {
    storage.exec("BEGIN IMMEDIATE");
    transactionOpen = true;
    if (!attestTeacherNoticeEmailOutboxSqliteSchema(storage)) {
      throw new Error("Teacher notice email outbox SQLite schema could not be attested.");
    }
    const result = await operation(storage);
    storage.exec("COMMIT");
    transactionOpen = false;
    return result;
  } catch (error) {
    operationFailed = true;
    if (transactionOpen) {
      try {
        storage.exec("ROLLBACK");
      } catch {
        // SQLite may already have rolled the transaction back after an error.
      }
    }
    throw error;
  } finally {
    try {
      storage.close();
    } catch (closeError) {
      // Preserve the original mutation/rollback error. On a successful
      // transaction, failure to close the dedicated handle must still surface.
      if (!operationFailed) throw closeError;
    }
  }
}

function getPostgresClient() {
  if (postgresClient) return postgresClient;
  if (!postgresUrl) {
    throw new Error("POSTGRES_URL is required when HK_MATH_STORAGE_PROVIDER=postgres.");
  }

  // Reused across serverless invocations via the module-level `postgresClient` singleton
  // so warm instances skip the TCP+TLS handshake. On Neon, POSTGRES_URL should point at the
  // POOLED endpoint (the `-pooler` host) so connections go through PgBouncer; `prepare: false`
  // is required in that mode (transaction pooling does not support prepared statements) and a
  // small `max` keeps each instance within the pooler's per-connection budget.
  postgresClient = postgres(postgresUrl, {
    max: postgresGeneralMaxConnections,
    idle_timeout: 20,
    connect_timeout: 10,
    prepare: false
  });
  return postgresClient;
}

async function hasCurrentPostgresSchemaMarker() {
  const sql = getPostgresClient();
  const rows = await sql<Array<{ ready: boolean }>>`
    SELECT (
      EXISTS (
        SELECT 1
        FROM auth_schema_migrations
        WHERE version = ${hotAuthSchemaVersion}
      )
      AND to_regclass('public.app_state') IS NOT NULL
    ) AS ready
  `;

  return rows[0]?.ready === true;
}

