function isStorageFreeExampleTeacher(userId: string) {
  const records = storageFreeExampleAccountRecordsFromAuthSessionPersistence(userId, {
    exampleAccountSeeds: seededExampleAccountSeeds,
    fixedExampleScopeForUserId: fixedExampleAccountScopeForUserId
  });
  return Boolean(records && canUseTeacherArea(records.user as UserRecord));
}

// Seeded example accounts authenticate through the storage-free fallback, so their
// sessions stay valid even when the mutable database has no matching user row. Write
// paths, however, look the user up in the database and reject the mutation. This
// provisions the missing example-account rows so those writes succeed.
export async function ensureExampleTeacherProvisioned(userId: string) {
  if (!isStorageFreeExampleTeacher(userId)) return false;

  const records = storageFreeExampleAccountRecordsFromAuthSessionPersistence(userId, {
    exampleAccountSeeds: seededExampleAccountSeeds,
    fixedExampleScopeForUserId: fixedExampleAccountScopeForUserId
  });
  if (!records) return false;

  return mutateDatabase((database) => {
    if (database.users.some((candidate) => candidate.id === userId)) return false;

    database.users.push(records.user as UserRecord);
    if (!database.student_profiles.some((candidate) => candidate.user_id === userId)) {
      database.student_profiles.push(records.profile as StudentProfileRecord);
    }
    if (!database.user_settings.some((candidate) => candidate.user_id === userId)) {
      database.user_settings.push(records.settings as UserSettingsRecord);
    }
    return true;
  });
}

