const isMainlandLessonKitTopic = (topic: TopicRecord, publisher?: TextbookPublisher) =>
  isMainlandLessonKitTopicFromTeacherOpsLessonKit(topic, publisher);

const mainlandLessonKitTopicOptions = (database: Database, classRecords: TeacherClassRecord[]) =>
  mainlandLessonKitTopicOptionsFromTeacherOpsLessonKit(database, classRecords);

function lessonKitGenerationQuestions(
  database: Database,
  teacherClass: TeacherClassRecord,
  topic: TopicRecord,
  publisher: TextbookPublisher
): TeacherLessonKitGenerationQuestion[] {
  const profile: CurriculumProfile = { region: "MAINLAND", publisher };
  const canonicalTopicId = topic.canonical_topic_id ?? topic.id;
  return database.questions
    .filter((question) =>
      question.grade === teacherClass.grade &&
      isCurriculumQuestion(question, profile) &&
      (question.topic_id === topic.id || question.canonical_topic_id === canonicalTopicId)
    )
    .sort((a, b) => a.difficulty.localeCompare(b.difficulty) || a.id.localeCompare(b.id))
    .slice(0, 10)
    .map((question) => ({
      id: question.id,
      prompt: { en: question.prompt_en, zh: question.prompt_zh, zhHans: question.prompt_zh },
      answer: question.answer,
      explanation: { en: question.explanation_en, zh: question.explanation_zh, zhHans: question.explanation_zh },
      difficulty: question.difficulty
    }));
}

function lessonKitGenerationContext(
  database: Database,
  kit: TeacherLessonKitRecord
): TeacherLessonKitGenerationContext | null {
  const teacherClass = database.teacher_classes.find((candidate) => candidate.id === kit.class_id);
  const topic = database.topics.find((candidate) => candidate.id === kit.topic_id && isMainlandLessonKitTopic(candidate, kit.textbook_publisher));
  if (!teacherClass || !topic) return null;

  const lesson = kit.lesson_slug
    ? database.lessons.find((candidate) => candidate.slug === kit.lesson_slug)
    : lessonForTopicFromStudentActivity(database, topic.id);
  const blocks = lesson
    ? database.lesson_blocks
        .filter((block) => block.lesson_slug === lesson.slug)
        .sort((a, b) => a.sort_order - b.sort_order)
        .slice(0, 6)
    : [];
  return {
    grade: kit.grade,
    gradeLabel: formatGradeLabel(kit.grade, "zh-Hans", true),
    publisher: kit.textbook_publisher,
    publisherLabel: publisherLabels[kit.textbook_publisher],
    topicId: topic.id,
    topicTitle: localizedTopicTitleForRecord(topic),
    lessonTitle: { en: kit.lesson_title_en, zh: kit.lesson_title_zh, zhHans: kit.lesson_title_zh },
    lessonPeriod: kit.lesson_period,
    lessonType: kit.lesson_type,
    durationMinutes: kit.duration_minutes,
    lessonDescription: lesson ? { en: lesson.description_en, zh: lesson.description_zh, zhHans: lesson.description_zh } : undefined,
    lessonBlockSummaries: blocks.map((block) => ({
      en: `${block.title_en}: ${block.content_en ?? ""}`.trim(),
      zh: `${block.title_zh}：${block.content_zh ?? ""}`.trim(),
      zhHans: `${block.title_zh}：${block.content_zh ?? ""}`.trim()
    })),
    practiceQuestions: lessonKitGenerationQuestions(database, teacherClass, topic, kit.textbook_publisher)
  };
}

