export const generateTeacherLessonKitWithAI = teacherOpsUserStore.generateTeacherLessonKitWithAI;

async function generateTeacherLessonKitSectionsWithAI(context: TeacherLessonKitGenerationContext) {
  const config = readLLMProviderConfig();
  if (!config.apiKey) return { status: "missing-config" as const };

  const messages: LLMProviderMessage[] = [
    {
      role: "system",
      content: "你只输出可解析 JSON。不得复制教材或教辅原文。所有内容必须便于教师审核。"
    },
    {
      role: "user",
      content: buildTeacherLessonKitLLMPrompt(context)
    }
  ];

  let data: unknown;
  try {
    const response = await fetch(config.apiUrl, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(buildLLMProviderRequestBody({
        model: config.model,
        messages,
        maxTokens: boundedLLMNumber(process.env.TEACHER_LESSON_KIT_MAX_TOKENS, 2600, 900, 5000),
        provider: config.provider,
        responseFormat: "json_object",
        deepSeekThinking: "disabled"
      }))
    });
    if (!response.ok) return { status: "provider-error" as const };
    data = await response.json();
  } catch {
    return { status: "provider-error" as const };
  }

  const sections = parseTeacherLessonKitSectionsFromLLM(extractLLMProviderReply(data));
  if (!sections) return { status: "invalid-output" as const };
  const usage = extractLLMProviderUsage(data);
  const finishReason = extractLLMProviderFinishReason(data);

  return {
    status: "generated" as const,
    sections,
    notesEn: `AI generated with ${config.model}; review required. Finish reason: ${finishReason ?? "unknown"}. Tokens: ${usage.totalTokens ?? "n/a"}.`,
    notesZh: `AI 已用 ${config.model} 生成；需教师审核。结束原因：${finishReason ?? "unknown"}。Token：${usage.totalTokens ?? "n/a"}。`
  };
}

