async function buildAIAssignmentGradingRun(database: Database, submission: SubmissionRecord, assignment: AssignmentRecord, attempt: AssignmentSubmissionAttemptRecord | null, now: string): Promise<AssignmentGradingRunRecord> {
  const fallback = deterministicAssignmentGradingRunFromTeacherOpsSubmission({
    database,
    submission,
    assignment,
    attempt,
    now,
    createId: randomUUID,
    questionAnswerMatches: (question, selectedAnswer) =>
      questionAnswerMatches(question as QuestionRecord, selectedAnswer)
  });
  const answerText = visibleAttemptTextFromTeacherOpsSubmission(attempt);
  if (!answerText) return fallback;

  const config = readLLMProviderConfig();
  if (!config.apiKey) return fallback;

  const prompt = [
    "You are a math teacher grading one student assignment submission.",
    "Return strict JSON with keys: suggestedScore number 0-100 or null, confidence number 0-1, feedback { en, zh }, correctionRequest { en, zh }.",
    "Do not finalize the grade; the human teacher will review your suggestion.",
    `Assignment title: ${assignment.title_en}`,
    `Assignment description: ${assignment.description_en}`,
    `Content type: ${assignment.content_type}`,
    `Target id: ${assignment.target_id ?? "none"}`,
    `Student answer text: ${answerText}`
  ].join("\n");
  const messages: LLMProviderMessage[] = [
    { role: "system", content: "Grade conservatively and give concise bilingual feedback for a teacher to approve." },
    { role: "user", content: prompt }
  ];
  const timeoutMs = boundedLLMNumber(process.env.ASSIGNMENT_GRADING_LLM_TIMEOUT_MS, 20000, 1000, 60000);
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(config.apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${config.apiKey}`
      },
      body: JSON.stringify(buildLLMProviderRequestBody({
        model: config.model,
        messages,
        maxTokens: 900,
        provider: config.provider,
        responseFormat: "json_object",
        deepSeekThinking: "disabled"
      })),
      signal: controller.signal
    });
    const payload: unknown = await response.json().catch(() => null);
    if (!response.ok) {
      return {
        ...fallback,
        id: `grading-run-${randomUUID()}`,
        status: "failed",
        provider: "llm",
        model: config.model,
        error_code: `LLM_HTTP_${response.status}`,
        created_at: now
      };
    }

    const parsed = parseAssignmentGradingJsonFromTeacherOpsSubmission(extractLLMProviderReply(payload));
    if (!parsed) {
      return {
        ...fallback,
        id: `grading-run-${randomUUID()}`,
        status: "failed",
        provider: "llm",
        model: config.model,
        error_code: extractLLMProviderFinishReason(payload) ?? "LLM_FORMAT_ERROR",
        usage: extractLLMProviderUsage(payload),
        created_at: now
      };
    }

    return {
      id: `grading-run-${randomUUID()}`,
      submission_id: submission.id,
      attempt_id: attempt?.id ?? null,
      status: parsed.confidence !== null && parsed.confidence >= 0.65 ? "suggested" : "needs-review",
      provider: "llm",
      model: config.model,
      suggested_score: parsed.suggestedScore,
      confidence: parsed.confidence,
      feedback_en: parsed.feedbackEn,
      feedback_zh: parsed.feedbackZh || parsed.feedbackEn,
      correction_request_en: parsed.correctionRequestEn,
      correction_request_zh: parsed.correctionRequestZh || parsed.correctionRequestEn,
      usage: extractLLMProviderUsage(payload),
      created_at: now
    };
  } catch (error) {
    return {
      ...fallback,
      id: `grading-run-${randomUUID()}`,
      status: "failed",
      provider: "llm",
      model: config.model,
      error_code: error instanceof Error && error.name === "AbortError" ? "LLM_TIMEOUT" : "LLM_REQUEST_FAILED",
      created_at: now
    };
  } finally {
    clearTimeout(timeout);
  }
}

