async function updateUserSettingsInPostgresHotTables(
  userId: string,
  patch: Partial<{ language: Language; theme: ThemeMode; selectedGrade: GradeId }>
) {
  if (!postgresHotAuthTablesEnabled()) return null;

  try {
    await ensurePostgresStateTable();
    return getPostgresClient().begin(async (sql) => {
      const hotRows = await readPostgresHotAuthRowsForUserIds(sql, [userId]);
      const user = hotRows.users.find((candidate) => candidate.id === userId);
      const profile = hotRows.studentProfiles.find((candidate) => candidate.user_id === userId);
      if (!user || !profile) return null;

      const fixedExampleScope = fixedExampleAccountScopeForUserId(userId);
      const nextProfile: StudentProfileRecord = fixedExampleScope
        ? {
            ...profile,
            name: user.username,
            grade: fixedExampleScope.grade,
            curriculum_track: curriculumTrackForProfile(fixedExampleScope.curriculumProfile),
            curriculum_region: fixedExampleScope.curriculumProfile.region,
            textbook_publisher: fixedExampleScope.curriculumProfile.publisher,
            avatar_id: isValidStudentAvatarIdFromAuthSessionPersistence(profile.avatar_id) ? profile.avatar_id : defaultStudentAvatarIdFromAuthSessionPersistence
          }
        : profile;

      if (fixedExampleScope) {
        const profileRow = hotAuthStudentProfileRows([nextProfile])[0];
        await sql`
          INSERT INTO auth_student_profiles ${sql([profileRow], "user_id", "name", "grade", "curriculum_track", "curriculum_region", "textbook_publisher", "parent_invite_code", "avatar_id", "avatar_image_data_url", "avatar_media_object_key")}
          ON CONFLICT (user_id) DO UPDATE SET
            name = excluded.name,
            grade = excluded.grade,
            curriculum_track = excluded.curriculum_track,
            curriculum_region = excluded.curriculum_region,
            textbook_publisher = excluded.textbook_publisher,
            parent_invite_code = excluded.parent_invite_code,
            avatar_id = excluded.avatar_id,
            avatar_image_data_url = excluded.avatar_image_data_url,
            avatar_media_object_key = excluded.avatar_media_object_key
        `;
      }

      const currentSettings =
        hotRows.userSettings.find((candidate) => candidate.user_id === userId) ?? defaultSettingsFromAuthSessionPersistence(userId, nextProfile.grade);
      const profileCurriculumProfile = fixedExampleScope?.curriculumProfile ?? profileForRecord(nextProfile);
      const canUpdateSelectedGrade = Boolean(
        patch.selectedGrade && authGradeAllowedForCurriculumProfile(patch.selectedGrade, profileCurriculumProfile)
      );
      const nextSettings: UserSettingsRecord = {
        ...currentSettings,
        language: patch.language && validLanguages.has(patch.language) ? patch.language : currentSettings.language,
        theme: patch.theme && validThemes.has(patch.theme) ? patch.theme : currentSettings.theme,
        selected_grade: selectedGradeForSettingsUpdateFromAuthSessionPersistence({
          currentSelectedGrade: currentSettings.selected_grade,
          fixedExampleGrade: fixedExampleScope?.grade,
          profileGrade: nextProfile.grade,
          requestedGrade: patch.selectedGrade,
          requestedGradeAllowed: canUpdateSelectedGrade,
          studentSelectedGradePolicy: canPersistStudentSelectedGrade,
          user: {
            id: user.id,
            role: user.role,
            curriculumProfile: profileCurriculumProfile
          }
        }),
        updated_at: new Date().toISOString()
      };
      const settingRow = hotAuthUserSettingRows([nextSettings])[0];
      await sql`
        INSERT INTO auth_user_settings ${sql([settingRow], "user_id", "language", "theme", "selected_grade", "updated_at")}
        ON CONFLICT (user_id) DO UPDATE SET
          language = excluded.language,
          theme = excluded.theme,
          selected_grade = excluded.selected_grade,
          updated_at = excluded.updated_at
      `;

      return authenticatedUserFromAuthRecordsFromAuthSessionPersistence({
        mediaObjectUrlForKey: mediaObjectAccessUrl,
        profile: nextProfile,
        settingsRecord: nextSettings,
        user
      });
    });
  } catch {
    return null;
  }
}

