export type AdaptiveUniverseSnapshot = {
  topics: Array<{ id: string; grade: GradeId }>;
  states: Array<{ skillId: string; pMastery: number; attemptCount: number; correctStreak: number; nextReviewAt: string | null }>;
  generatedAt: string;
};

export async function getAdaptiveUniverseSnapshot({
  userId,
  curriculumTrack = defaultCurriculumProfile
}: {
  userId: string;
  curriculumTrack?: CurriculumScope;
}): Promise<AdaptiveUniverseSnapshot> {
  const database = await readDatabase();
  const topics = database.topics
    .filter((topic) => isCurriculumTopic(topic, curriculumTrack))
    .map((topic) => ({ id: topic.id, grade: topic.grade as GradeId }));
  const topicIds = new Set(topics.map((topic) => topic.id));
  const states = adaptiveStatesForUser(database, userId)
    .filter((state) => {
      const separator = state.skillId.lastIndexOf(":");
      return topicIds.has(separator === -1 ? state.skillId : state.skillId.slice(0, separator));
    })
    .map((state) => ({
      skillId: state.skillId,
      pMastery: state.pMastery,
      attemptCount: state.attemptCount,
      correctStreak: state.correctStreak,
      nextReviewAt: state.nextReviewAt
    }));
  return { topics, states, generatedAt: new Date().toISOString() };
}

export type TeacherClassSkyMaterials = {
  className: string;
  classGrade: GradeId;
  curriculumTrack: CurriculumTrack | null;
  studentCount: number;
  topics: Array<{ id: string; grade: GradeId }>;
  /** Anonymous per-student state lists — aggregated before leaving the API layer. */
  students: Array<{
    grade: GradeId;
    states: Array<{ skillId: string; pMastery: number; attemptCount: number; correctStreak: number; nextReviewAt: string | null }>;
  }>;
  generatedAt: string;
};

export async function getTeacherClassSkyMaterials({
  teacherId,
  classId
}: {
  teacherId: string;
  classId: string;
}): Promise<TeacherClassSkyMaterials | null> {
  const enrollments = await getTeacherClassEnrollments(teacherId, classId);
  if (!enrollments) return null;
  const classes = await getTeacherClasses(teacherId);
  const teacherClass = classes?.find((candidate) => candidate.id === classId) ?? null;
  if (!teacherClass) return null;

  const database = await readDatabase();
  const curriculumScope = (teacherClass.curriculumProfile ?? teacherClass.curriculumTrack ?? defaultCurriculumProfile) as CurriculumScope;
  const topics = database.topics
    .filter((topic) => isCurriculumTopic(topic, curriculumScope))
    .map((topic) => ({ id: topic.id, grade: topic.grade as GradeId }));
  const topicIds = new Set(topics.map((topic) => topic.id));

  const students = enrollments.map((enrollment) => ({
    grade: enrollment.studentGrade,
    states: adaptiveStatesForUser(database, enrollment.studentId)
      .filter((state) => {
        const separator = state.skillId.lastIndexOf(":");
        return topicIds.has(separator === -1 ? state.skillId : state.skillId.slice(0, separator));
      })
      .map((state) => ({
        skillId: state.skillId,
        pMastery: state.pMastery,
        attemptCount: state.attemptCount,
        correctStreak: state.correctStreak,
        nextReviewAt: state.nextReviewAt
      }))
  }));

  return {
    className: teacherClass.name,
    classGrade: teacherClass.grade,
    curriculumTrack: teacherClass.curriculumTrack ?? null,
    studentCount: enrollments.length,
    topics,
    students,
    generatedAt: new Date().toISOString()
  };
}

/**
 * Consolidated gradebook grid for one class: every graded item (assignments and
 * assessments) as columns, every enrolled student as a row. Ownership is enforced
 * by `getTeacherClassEnrollments`, which returns null when the teacher does not
 * own the class; the database is then read once to assemble the grid.
 */
export async function getTeacherGradebookData({
  teacherId,
  classId
}: {
  teacherId: string;
  classId: string;
}): Promise<TeacherGradebookData | null> {
  const enrollments = await getTeacherClassEnrollments(teacherId, classId);
  if (!enrollments) return null;
  const classes = await getTeacherClasses(teacherId);
  const teacherClass = classes?.find((candidate) => candidate.id === classId) ?? null;
  if (!teacherClass) return null;

  const database = await readDatabase();

  const students = [...enrollments]
    .sort((a, b) => a.studentName.localeCompare(b.studentName))
    .map((enrollment) => ({ studentId: enrollment.studentId, studentName: enrollment.studentName }));

  const assignments = database.assignments
    .filter((assignment) => assignment.class_id === classId)
    .map((assignment) => ({
      id: assignment.id,
      title: { en: assignment.title_en, zh: assignment.title_zh },
      status: assignment.status,
      dueAt: assignment.due_at,
      countsTowardsGrade: assignment.count_towards_grade,
      createdAt: assignment.created_at,
      submissions: database.submissions
        .filter((submission) => submission.assignment_id === assignment.id)
        .map((submission) => ({
          studentId: submission.student_id,
          status: submission.status,
          score: submission.score
        }))
    }));

  const assessments = database.assessments
    .filter((assessment) => assessment.class_id === classId)
    .map((assessment) => ({
      id: assessment.id,
      title: { en: assessment.title_en, zh: assessment.title_zh },
      type: assessment.type,
      status: assessment.status,
      closesAt: assessment.closes_at,
      weight: assessment.grade_weight,
      createdAt: assessment.created_at,
      submissions: database.assessment_submissions
        .filter((submission) => submission.assessment_id === assessment.id)
        .map((submission) => ({
          studentId: submission.student_id,
          status: submission.status,
          attemptNumber: submission.attempt_number,
          score: submission.score,
          maxScore: submission.max_score
        }))
    }));

  return buildTeacherGradebook({
    class: { id: teacherClass.id, name: teacherClass.name, grade: teacherClass.grade },
    students,
    assignments,
    assessments
  });
}

export async function getTeacherGradebookCsv({
  teacherId,
  classId
}: {
  teacherId: string;
  classId: string;
}): Promise<string | null> {
  const data = await getTeacherGradebookData({ teacherId, classId });
  if (!data) return null;
  return gradebookToCsv(data);
}

