async function getFastPostgresLessonEntryTarget(
  userId: string,
  grade: GradeId,
  curriculumTrack: CurriculumScope = defaultCurriculumProfile
): Promise<LessonEntryTarget | null | undefined> {
  if (storageProvider !== "postgres") return undefined;

  const profile = curriculumProfileForScope(curriculumTrack);
  if (!curriculumContentEnabledFor(profile)) return null;
  const track = curriculumTrackForProfile(profile);

  try {
    await ensurePostgresStateTable();
    const sql = getPostgresClient();
    const rows = await sql<Array<{ slug: string | null; grade: string | null; topic_id: string | null }>>`
      WITH state AS (
        SELECT payload
        FROM app_state
        WHERE id = ${stateRecordId}
      ),
      matching_topics AS (
        SELECT
          topic_items.topic_record,
          COALESCE((topic_items.topic_record->>'sort_order')::integer, 999999) AS topic_sort_order
        FROM state
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(state.payload->'topics', '[]'::jsonb)) AS topic_items(topic_record)
        WHERE topic_items.topic_record->>'grade' = ${grade}
          AND CASE
            WHEN topic_items.topic_record->>'curriculum_track' = 'MAINLAND_PEP_HIGH'
              THEN COALESCE(topic_items.topic_record->>'textbook_publisher', 'MAINLAND_PEP') = ${profile.publisher}
            WHEN topic_items.topic_record->>'curriculum_track' IN ('US_CA_MATH', 'US_NC_MATH', 'US_AR_MATH', 'US_FL_MATH')
              THEN topic_items.topic_record->>'curriculum_track' = ${track}
            WHEN topic_items.topic_record->>'curriculum_track' = 'HK'
              THEN ${profile.region} = 'HK'
            WHEN topic_items.topic_record ? 'textbook_publisher'
              THEN topic_items.topic_record->>'textbook_publisher' = ${profile.publisher}
            WHEN topic_items.topic_record ? 'curriculum_region'
              THEN topic_items.topic_record->>'curriculum_region' = ${profile.region}
            ELSE FALSE
          END
      ),
      lesson_candidates AS (
        SELECT
          ROW_NUMBER() OVER (
            ORDER BY matching_topics.topic_sort_order, matching_topics.topic_record->>'id'
          ) - 1 AS candidate_index,
          matching_topics.topic_record,
          lesson_items.lesson_record
        FROM state
        CROSS JOIN matching_topics
        JOIN LATERAL (
          SELECT lesson_record
          FROM jsonb_array_elements(COALESCE(state.payload->'lessons', '[]'::jsonb)) AS lesson_items(lesson_record)
          WHERE lesson_record->>'topic_id' = matching_topics.topic_record->>'id'
          ORDER BY lesson_record->>'slug'
          LIMIT 1
        ) AS lesson_items ON TRUE
      ),
      candidates_with_progress AS (
        SELECT
          lesson_candidates.*,
          progress_items.progress_record,
          COALESCE(progress_items.progress_record->>'status', 'not-started') AS progress_status,
          COALESCE(
            progress_items.progress_record->>'updated_at',
            progress_items.progress_record->>'started_at',
            progress_items.progress_record->>'completed_at',
            ''
          ) AS progress_timestamp,
          (
            progress_items.progress_record IS NOT NULL AND
            COALESCE(progress_items.progress_record->>'status', 'not-started') <> 'completed' AND
            (
              COALESCE(progress_items.progress_record->>'status', 'not-started') <> 'not-started' OR
              COALESCE(NULLIF(progress_items.progress_record->>'mastery', '')::numeric, 0) > 0 OR
              COALESCE(NULLIF(progress_items.progress_record->>'duration_seconds', '')::numeric, 0) > 0 OR
              NULLIF(progress_items.progress_record->>'started_at', '') IS NOT NULL
            )
          ) AS has_active_progress
        FROM state
        CROSS JOIN lesson_candidates
        LEFT JOIN LATERAL (
          SELECT progress_record
          FROM jsonb_array_elements(COALESCE(state.payload->'lesson_progress', '[]'::jsonb)) AS progress_items(progress_record)
          WHERE progress_record->>'user_id' = ${userId}
            AND (
              progress_record->>'lesson_slug' = lesson_candidates.lesson_record->>'slug' OR
              progress_record->>'topic_id' = lesson_candidates.lesson_record->>'topic_id'
            )
          ORDER BY COALESCE(progress_record->>'updated_at', progress_record->>'started_at', progress_record->>'completed_at', '') DESC
          LIMIT 1
        ) AS progress_items ON TRUE
      ),
      completed_anchor AS (
        SELECT MAX(candidate_index) AS candidate_index
        FROM candidates_with_progress
        WHERE progress_status = 'completed'
      ),
      ranked_candidates AS (
        SELECT
          candidates_with_progress.*,
          CASE
            WHEN has_active_progress THEN 0
            WHEN (SELECT candidate_index FROM completed_anchor) IS NOT NULL
              AND candidate_index > (SELECT candidate_index FROM completed_anchor) THEN 1
            WHEN (SELECT candidate_index FROM completed_anchor) IS NOT NULL
              AND candidate_index = (SELECT candidate_index FROM completed_anchor) THEN 2
            ELSE 3
          END AS entry_rank
        FROM candidates_with_progress
      )
      SELECT
        lesson_record->>'slug' AS slug,
        COALESCE(lesson_record->>'grade', topic_record->>'grade') AS grade,
        lesson_record->>'topic_id' AS topic_id
      FROM ranked_candidates
      ORDER BY
        entry_rank,
        CASE WHEN entry_rank = 0 THEN progress_timestamp END DESC,
        CASE WHEN entry_rank = 1 THEN candidate_index END ASC,
        CASE WHEN entry_rank = 2 THEN candidate_index END DESC,
        CASE WHEN entry_rank = 3 THEN candidate_index END ASC
      LIMIT 1
    `;

    const row = rows[0];
    if (!row?.slug || !row.topic_id || !validGrades.has(row.grade as GradeId)) return null;

    return {
      href: lessonHrefForSlug(row.slug),
      slug: row.slug,
      grade: row.grade as GradeId,
      topicId: row.topic_id
    };
  } catch {
    return undefined;
  }
}

