export type {
  AITutorDataScope,
  AITutorDatabaseContextOptions,
  AITutorDatabaseContextResult
};

async function buildAITutorDatabaseContextFromDatabase(
  database: Database,
  userId: string,
  context?: AITutorDatabaseContextOptions
): Promise<AITutorDatabaseContextResult> {
  const lines: string[] = ["Database-backed personalization:"];
  const fallbackLines: string[] = [];
  const includedScopes: AITutorDataScope[] = [];
  const deniedScopes: AITutorDataScope[] = [];
  const language = context?.language ?? "en";
  const user = database.users.find((candidate) => candidate.id === userId) ?? null;
  const authenticated = user ? toAuthenticatedUser(database, user) : null;
  const scopeSet = aiTutorRequestedScopeSetFromAiGovernancePersistence(context?.dataScopes);
  const { requestedQuestion, requestedTopic } = aiTutorRequestedDatabaseRecordsFromAiGovernancePersistence({
    context,
    database,
    questionForId,
    topicRecordForId
  });
  const {
    subjectCurriculumTrack,
    subjectGrade,
    subjectName,
    subjectUserId,
    targetStudentId,
    verifiedTargetProfile
  } = await aiTutorDatabaseContextSubjectFromAiGovernancePersistence({
    authenticated,
    context,
    defaultCurriculumTrack,
    resolveTeacherStudentProfile: getTeacherStudentProfileData,
    user,
    userId
  });
  const scopeAccess = aiTutorContextScopeAccessFromAiGovernancePersistence({
    targetStudentId,
    user,
    userId,
    verifiedTargetProfile
  });

  lines.push(...tutorCurriculumPolicyLinesFromAiGovernancePersistence(subjectCurriculumTrack));

  const { topicId, question } = aiTutorRequestedCurriculumContextFromAiGovernancePersistence({
    isCurriculumQuestion,
    isCurriculumTopic,
    requestedQuestion,
    requestedTopic,
    subjectCurriculumTrack
  });

  if (question) {
    lines.push(...tutorCurrentQuestionContextLinesFromAiGovernancePersistence({
      allowAnswerReference: context?.allowAnswerReference,
      answer: question.answer,
      explanation: question.explanation_en,
      prompt: question.prompt_en,
      topicLabel: topicLabelFor(database, question).en
    }));
  }

  const lessonContext = aiTutorLessonContextInputFromAiGovernancePersistence(database, {
    isCurriculumTopic,
    lessonForTopic: (topicId) => lessonForTopicFromStudentActivity(database, topicId),
    lessonProgressFor: (lesson) => lessonProgressFor(database, userId, lesson),
    lessonSlug: context?.lessonSlug,
    subjectCurriculumTrack,
    topicForLesson: (lesson) => topicRecordForId(database, lesson.topic_id),
    topicId
  });
  if (lessonContext) {
    lines.push(...tutorLessonProgressContextLinesFromAiGovernancePersistence({
      mastery: lessonContext.mastery,
      status: lessonContext.status,
      title: lessonContext.title
    }));
  }

  lines.push(...tutorRecentAttemptContextLinesFromAiGovernancePersistence(
    aiTutorRecentAttemptContextInputsFromAiGovernancePersistence(database, {
      isCurriculumQuestion,
      questionForId: (questionId) => questionForId(database, questionId),
      subjectCurriculumTrack,
      topicId,
      topicLabelForQuestion: (question) => topicLabelFor(database, question).en,
      userId
    })
  ));

  lines.push(...tutorRecentMistakeContextLinesFromAiGovernancePersistence(
    aiTutorRecentMistakeContextInputsFromAiGovernancePersistence(database, {
      isCurriculumQuestion,
      questionForId: (questionId) => questionForId(database, questionId),
      subjectCurriculumTrack,
      topicId,
      userId
    })
  ));

  lines.push(...tutorRecentTutorMessageContextLinesFromAiGovernancePersistence(
    aiTutorRecentMessageContextInputsFromAiGovernancePersistence(database, userId)
  ));

  const studentDashboardContext = await aiTutorStudentDashboardScopeContextFromAiGovernancePersistence({
    canReadStudentDashboard: scopeAccess.canReadStudentDashboard,
    getDashboardData: () => getDashboardData(subjectUserId, subjectGrade, subjectCurriculumTrack),
    grade: subjectGrade,
    language,
    learnerName: subjectName,
    scopeSet
  });
  mergeAiTutorScopeContextResultFromAiGovernancePersistence(
    { deniedScopes, fallbackLines, includedScopes, lines },
    studentDashboardContext
  );

  const teacherDashboardContext = await aiTutorTeacherDashboardScopeContextFromAiGovernancePersistence({
    canReadTeacherDashboard: scopeAccess.canReadTeacherDashboard,
    getTeacherDashboardData: () => getTeacherDashboardData(userId),
    language,
    scopeSet
  });
  mergeAiTutorScopeContextResultFromAiGovernancePersistence(
    { deniedScopes, fallbackLines, includedScopes, lines },
    teacherDashboardContext
  );

  const teacherStudentProfileContext = aiTutorTeacherStudentProfileScopeContextFromAiGovernancePersistence({
    canReadTeacherStudentProfile: scopeAccess.canReadTeacherStudentProfile,
    language,
    profile: verifiedTargetProfile,
    scopeSet
  });
  mergeAiTutorScopeContextResultFromAiGovernancePersistence(
    { deniedScopes, fallbackLines, includedScopes, lines },
    teacherStudentProfileContext
  );

  const adaptiveEngineContext = await aiTutorAdaptiveEngineScopeContextFromAiGovernancePersistence({
    canReadAdaptiveEngine: scopeAccess.canReadAdaptiveEngine,
    curriculumTrack: subjectCurriculumTrack,
    getAdaptiveLearningDecision,
    grade: subjectGrade,
    language,
    learnerName: subjectName,
    scopeSet,
    topicId,
    userId: subjectUserId
  });
  mergeAiTutorScopeContextResultFromAiGovernancePersistence(
    { deniedScopes, fallbackLines, includedScopes, lines },
    adaptiveEngineContext
  );

  return aiTutorDatabaseContextResultFromAiGovernancePersistence({
    deniedScopes,
    fallbackLines,
    includedScopes,
    lines,
    subjectUserId
  });
}

export const buildAITutorDatabaseContext = aiGovernanceUserStore.buildAITutorDatabaseContext;

